RKfill("slw",[{"b":["<b>Slicing</b> adalah mengubah desain statis (Figma, Adobe XD, Penpot) menjadi halaman web atau aplikasi yang benar-benar berjalan. Istilah ini berasal dari zaman dulu, saat desain Photoshop \"diiris\" menjadi potongan gambar. Sekarang yang diiris adalah <b>struktur</b>: section, komponen, dan token.","Alur kerja slicer profesional: (1) <b>pelajari desain</b> secara utuh, termasuk versi mobile dan desktop; (2) <b>pecah halaman</b> menjadi section (navbar, hero, fitur, testimoni, harga, footer); (3) temukan <b>komponen berulang</b> (tombol, kartu, input); (4) catat <b>token</b> (warna, font, spacing, radius); (5) siapkan <b>aset</b> (ikon SVG, gambar WebP); (6) tulis <b>HTML semantik</b> dulu; (7) tulis CSS <b>mobile-first</b>; (8) bandingkan dengan desain (<b>pixel-perfect</b>); (9) uji di perangkat nyata.","Kesalahan pemula: langsung menulis CSS dari section paling atas sampai bawah tanpa melihat pola. Hasilnya tombol yang sama ditulis lima kali dengan ukuran sedikit berbeda. Luangkan 15 menit di awal untuk mencatat komponen dan token, dan kamu akan menghemat berjam-jam."],"tb":[{"c":"Pembagian halaman landing page","h":["Section","Elemen HTML","Komponen di dalamnya"],"r":[["Navbar","header > nav","Logo, link, tombol masuk, tombol menu (mobile)"],["Hero","section","Judul, deskripsi, 2 tombol, gambar"],["Fitur","section","Kartu fitur × 3 sampai 6 (ikon, judul, teks)"],["Testimoni","section","Kartu kutipan, foto, nama"],["Harga","section","Kartu paket × 3, lencana \"Paling populer\""],["Footer","footer","Link, form newsletter, hak cipta"]]}],"pts":["Slicing = desain statis menjadi kode yang berjalan.","Pecah section, temukan komponen dan token dulu.","HTML semantik dulu, lalu CSS mobile-first."],"q":[["Langkah yang sebaiknya dilakukan sebelum menulis CSS?",["Mencatat komponen berulang dan token","Mengekspor semua frame jadi PNG","Menulis JavaScript"],0,"Pola dulu, kode kemudian."],["Kenapa slicing dimulai dari mobile?",["Layar kecil lebih mudah diperluas daripada sebaliknya","Desainer selalu mulai dari mobile","Aturan Figma"],0,"Mobile-first: tambahkan aturan saat layar melebar."]],"so":[{"q":"Ambil satu landing page yang kamu suka. Pecah menjadi section, lalu daftar komponen berulang dan token warna yang kamu temukan.","h":"Tulis section dari atas ke bawah, lalu cari elemen yang sama bentuknya.","a":"Contoh:\nSection : navbar, hero, logo klien, fitur (6 kartu), testimoni, harga (3 paket), FAQ, footer\nKomponen: tombol (primary, secondary), kartu fitur, kartu harga, item FAQ\nToken   : brand #4F46E5, teks #111827, abu #6B7280, latar #F9FAFB, radius 12, spacing 8/16/24/48","lang":"text"}]},{"b":["<b>Dev Mode</b> (ikon &lt;/&gt; atau Shift + D di Figma) adalah tampilan khusus developer. Klik elemen untuk melihat <b>ukuran</b>, <b>jarak</b> ke elemen lain (tahan Alt atau Option sambil mengarahkan kursor), <b>warna</b> dan nama variabelnya, <b>tipografi</b>, serta potongan kode CSS. Developer tidak bisa mengubah desain secara tidak sengaja di mode ini.","Cara membaca auto layout: frame dengan auto layout ditampilkan sebagai <code>display: flex</code>, lengkap dengan <code>gap</code>, <code>padding</code>, dan arah. Hug contents berarti lebar mengikuti isi, Fill container berarti <code>flex: 1</code> atau <code>width: 100%</code>. Jangan menyalin <code>position: absolute</code> dan <code>width</code> piksel tetap dari panel kode mentah-mentah; itu hanya cocok untuk ukuran frame itu saja.","Kebiasaan baik: periksa nama <b>variabel</b> (misalnya <code>color/brand/600</code>) dan pakai nama itu di CSS, bukan kode hex. Periksa juga apakah frame ditandai <b>Ready for dev</b>; frame lain mungkin masih eksplorasi. Jika tidak punya akses Dev Mode (berbayar), mode Inspect di akun gratis tetap menampilkan ukuran dan warna."],"tb":[{"c":"Figma ke CSS","h":["Di Figma","Di CSS"],"r":[["Auto layout horizontal, gap 16","display: flex; gap: 16px"],["Auto layout vertical","display: flex; flex-direction: column"],["Padding 24 / 16","padding: 24px 16px"],["Hug contents","width: auto (atau fit-content)"],["Fill container","flex: 1 atau width: 100%"],["Corner radius 12","border-radius: 12px"],["Drop shadow 0 4 12 #0000001F","box-shadow: 0 4px 12px rgb(0 0 0 / .12)"],["Text Inter 16/24 Medium","font: 500 16px/24px Inter"],["Constraints Left & Right","lebar melar mengikuti induk"],["Layer opacity 60%","opacity: .6"]]}],"pts":["Dev Mode: ukuran, jarak, variabel, kode.","Auto layout = flexbox; jangan salin posisi absolut mentah.","Pakai nama variabel, cek status Ready for dev."],"q":[["Cara melihat jarak antara dua elemen di Figma?",["Pilih satu elemen, tahan Alt/Option, arahkan ke elemen lain","Klik kanan lalu Measure","Tidak bisa"],0,"Figma menampilkan jarak merah."],["Panel kode Figma menulis position: absolute; left: 132px. Sebaiknya?",["Salin persis","Terjemahkan ke flex atau grid sesuai auto layout","Abaikan elemennya"],1,"Posisi absolut hanya pas di satu ukuran frame."]],"so":[{"q":"Dev Mode menampilkan: auto layout vertical, gap 12, padding 20/24, fill #F8FAFC, radius 16, stroke 1 #E2E8F0, shadow 0 2 8 #0F172A14. Tulis CSS-nya.","h":"Terjemahkan satu per satu, warna alpha 14 hex ≈ 8%.","a":".kartu {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  padding: 20px 24px;\n  background: #F8FAFC;\n  border: 1px solid #E2E8F0;\n  border-radius: 16px;\n  box-shadow: 0 2px 8px rgb(15 23 42 / .08);\n}","lang":"css"}]},{"b":["Langkah pertama menulis CSS dari desain: pindahkan <b>token</b> ke <code>:root</code>. Buka panel Variables di Figma (atau Local styles untuk file lama) dan salin warna, font, spacing, radius, dan bayangan menjadi CSS variables.","Setelah token ada, <b>semua</b> aturan CSS memakai <code>var(--...)</code>. Jika desainer mengubah warna merek minggu depan, kamu cukup mengubah satu baris. Jika desain punya mode gelap, tambahkan blok token kedua.","Beri nama variabel sama seperti di Figma agar mudah dicocokkan: <code>color/brand/600</code> menjadi <code>--color-brand-600</code>, <code>spacing/4</code> menjadi <code>--spacing-4</code>.","Desain di pratinjau memakai warna merek #0F766E dan radius 12. Pindahkan ke token."],"html":"<section class=\"promo\">\n  <h2>Kelas baru: Slicing Website</h2>\n  <p>Ubah desain Figma menjadi halaman nyata.</p>\n  <a class=\"tombol\" href=\"#\">Daftar</a>\n</section>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n:root {\n  /* token dari Figma: tulis di sini */\n}\n.promo { margin: 16px; padding: 24px; border-radius: 12px; background: #CCFBF1; }\n.promo h2 { margin: 0 0 8px; color: #134E4A; }\n.tombol { display: inline-block; margin-top: 8px; padding: 12px 24px; border-radius: 12px; background: #0F766E; color: #fff; text-decoration: none; font-weight: 600; }","task":{"q":"Buat token <code>--color-brand-600: #0F766E</code> dan <code>--radius-md: 12px</code> di <code>:root</code>, lalu pakai keduanya di <code>.tombol</code>.","test":"getComputedStyle(document.documentElement).getPropertyValue('--color-brand-600').trim().toLowerCase()==='#0f766e'&&[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText==='.tombol'&&/var\\(--color-brand-600\\)/.test(r.style.cssText)&&/var\\(--radius-md\\)/.test(r.style.cssText))","hint":":root { --color-brand-600: #0F766E; --radius-md: 12px } lalu .tombol { background: var(--color-brand-600); border-radius: var(--radius-md) }"},"pts":["Token dari Figma Variables ke :root.","Semua aturan memakai var().","Nama variabel sama dengan nama di Figma."],"q":[["Nama CSS yang cocok untuk variabel Figma spacing/4?",["--spacing-4","--s4px","--jarak"],0,"Sama dengan nama di Figma."]],"so":[{"q":"Ubah daftar variabel Figma berikut menjadi CSS: color/brand/500 #6366F1, color/text/primary #111827, spacing/2 8, spacing/4 16, radius/lg 16, font/body Inter.","h":"Garis miring menjadi tanda hubung, angka spacing diberi px.","a":":root {\n  --color-brand-500: #6366F1;\n  --color-text-primary: #111827;\n  --spacing-2: 8px;\n  --spacing-4: 16px;\n  --radius-lg: 16px;\n  --font-body: \"Inter\", system-ui, sans-serif;\n}","lang":"css"}]},{"b":["Desain hanya menunjukkan <b>rupa</b>; slicer yang menentukan <b>makna</b>. Navbar adalah <code>&lt;header&gt;</code> berisi <code>&lt;nav&gt;</code>, isi utama adalah <code>&lt;main&gt;</code>, setiap bagian adalah <code>&lt;section&gt;</code> dengan judul, kartu artikel adalah <code>&lt;article&gt;</code>, dan bagian bawah adalah <code>&lt;footer&gt;</code>.","Judul harus berurutan: satu <code>&lt;h1&gt;</code> per halaman (biasanya judul hero), lalu <code>&lt;h2&gt;</code> untuk judul section, <code>&lt;h3&gt;</code> untuk judul kartu. Pilih tag berdasarkan <b>tingkat</b>, bukan ukuran huruf di desain; ukuran diatur oleh CSS.","Yang terlihat seperti tombol tetapi pindah halaman adalah <code>&lt;a&gt;</code>; yang menjalankan aksi di halaman yang sama adalah <code>&lt;button&gt;</code>. HTML semantik membuat halaman terbaca pembaca layar, mudah ditemukan Google, dan lebih mudah di-styling.","Kerangka di pratinjau hanya berisi div. Ganti dengan landmark yang tepat."],"html":"<div class=\"atas\"><div class=\"logo\">RuangKode</div><div class=\"menu\"><a href=\"#\">Kelas</a><a href=\"#\">Harga</a></div></div>\n<div class=\"isi\">\n  <div class=\"judul-besar\">Belajar slicing dari desain nyata</div>\n  <p>Latihan dengan file Figma sungguhan.</p>\n</div>\n<div class=\"bawah\">© 2026 RuangKode</div>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.atas, header { display: flex; justify-content: space-between; align-items: center; padding: 16px; border-bottom: 1px solid #E4E7EB; }\n.menu, nav { display: flex; gap: 16px; }\n.isi, main { padding: 24px 16px; }\n.judul-besar, h1 { font-size: 28px; font-weight: 700; margin: 0 0 8px; }\n.bawah, footer { padding: 16px; color: #52606D; font-size: 14px; }","task":{"q":"Ganti kerangkanya: <code>header</code> berisi <code>nav</code>, <code>main</code> berisi <code>h1</code>, dan <code>footer</code>.","test":"!!document.querySelector('header nav')&&!!document.querySelector('main h1')&&!!document.querySelector('footer')","hint":"<header><div class=\"logo\">RuangKode</div><nav>...</nav></header><main><h1>...</h1><p>...</p></main><footer>...</footer>"},"pts":["header, nav, main, section, article, footer.","Satu h1, judul berurutan.","Pindah halaman: a. Aksi di halaman: button."],"q":[["Tombol \"Lihat kelas\" yang membuka halaman lain sebaiknya memakai?",["button","a","div"],1,"Navigasi memakai tautan."],["Berapa h1 dalam satu halaman?",["Satu","Satu per section","Bebas"],0,"h1 adalah judul halaman."]],"so":[{"q":"Tulis kerangka HTML semantik untuk halaman blog: navbar, judul artikel, info penulis, isi, artikel terkait (3 kartu), footer.","h":"header/nav, main/article, aside atau section, footer.","a":"<header><nav>...</nav></header>\n<main>\n  <article>\n    <h1>Judul artikel</h1>\n    <p class=\"meta\">Oleh Rina · 5 menit baca</p>\n    <p>Isi...</p>\n  </article>\n  <section aria-labelledby=\"terkait\">\n    <h2 id=\"terkait\">Artikel terkait</h2>\n    <article><h3>...</h3></article>\n    <article><h3>...</h3></article>\n    <article><h3>...</h3></article>\n  </section>\n</main>\n<footer>...</footer>","lang":"html"}]},{"b":["Navbar di desain biasanya: logo di kiri, link di tengah atau kanan, tombol aksi di kanan. Di CSS cukup flexbox: <code>display: flex; justify-content: space-between; align-items: center</code>.","Di mobile, link biasanya disembunyikan di balik tombol menu (hamburger). Cara tanpa JavaScript: <code>&lt;details&gt;</code> dan <code>&lt;summary&gt;</code>. Cara umum: tombol dengan <code>aria-expanded</code> yang mengubah kelas menu lewat JavaScript. Ukur tinggi navbar dari desain (biasanya 56 sampai 72 px) dan pastikan setiap link punya area klik yang cukup.","Untuk navbar yang tetap terlihat saat menggulir, pakai <code>position: sticky; top: 0</code> dan beri latar serta <code>z-index</code> agar konten tidak tembus.","Navbar di pratinjau masih menumpuk. Susun dengan flexbox."],"html":"<header class=\"nav\">\n  <a class=\"logo\" href=\"#\">Kopi<b>Nusa</b></a>\n  <nav class=\"link\"><a href=\"#\">Menu</a><a href=\"#\">Lokasi</a><a href=\"#\">Tentang</a></nav>\n  <a class=\"cta\" href=\"#\">Pesan</a>\n</header>\n<main style=\"padding:16px\">Konten halaman...</main>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.nav { padding: 12px 16px; border-bottom: 1px solid #E7E0D8; background: #FFFBF5; }\n.logo { font-size: 20px; color: #3E2723; text-decoration: none; }\n.link { display: flex; gap: 16px; }\n.link a { color: #5D4037; text-decoration: none; padding: 8px 0; }\n.cta { background: #6D4C41; color: #fff; padding: 8px 16px; border-radius: 999px; text-decoration: none; }","task":{"q":"Jadikan <code>.nav</code> flex: <code>display: flex; justify-content: space-between; align-items: center</code>, dan buat navbar menempel saat menggulir (<code>position: sticky; top: 0</code>).","test":"(s=>s.display==='flex'&&s.justifyContent==='space-between'&&s.position==='sticky')(getComputedStyle(document.querySelector('.nav')))","hint":".nav { display: flex; justify-content: space-between; align-items: center; gap: 16px; position: sticky; top: 0 }"},"pts":["Navbar: flex + space-between + align-items center.","Mobile: menu tersembunyi dengan aria-expanded.","Sticky: position sticky, top 0, latar, z-index."],"q":[["Properti yang mendorong logo ke kiri dan tombol ke kanan?",["justify-content: space-between","text-align: justify","float: right"],0,"Ruang dibagi di antara item."]],"so":[{"q":"Buat navbar dengan tombol menu mobile tanpa JavaScript memakai details dan summary.","h":"summary menjadi tombol, isi details adalah daftar link.","a":"<header class=\"nav\">\n  <a class=\"logo\" href=\"/\">KopiNusa</a>\n  <details class=\"menu-m\">\n    <summary aria-label=\"Buka menu\">☰</summary>\n    <nav><a href=\"#menu\">Menu</a><a href=\"#lokasi\">Lokasi</a><a href=\"#tentang\">Tentang</a></nav>\n  </details>\n</header>","lang":"html"}]},{"b":["<b>Hero</b> adalah section pertama yang dilihat pengunjung: judul (h1), satu sampai dua kalimat penjelas, satu sampai dua tombol, dan gambar. Di desktop biasanya dua kolom (teks kiri, gambar kanan); di mobile menjadi satu kolom dengan gambar di bawah atau di atas teks.","Ukur dari desain: lebar maksimum teks, jarak judul ke deskripsi, jarak ke tombol. Judul hero memakai ukuran fluid (<code>clamp()</code>) agar tidak terlalu besar di ponsel.","Dua tombol berdampingan bisa terlalu lebar di ponsel kecil. Pakai <code>display: flex; flex-wrap: wrap; gap: 12px</code> agar tombol kedua turun ke baris baru jika tidak muat, bukan memaksa halaman melebar.","Grup tombol di pratinjau belum bisa turun baris."],"html":"<section class=\"hero\">\n  <div class=\"teks\">\n    <h1>Kopi lokal, diseduh hari ini</h1>\n    <p>Biji kopi dari Gayo, Toraja, dan Kintamani. Diantar hangat dalam 30 menit.</p>\n    <div class=\"aksi\"><a class=\"btn utama\" href=\"#\">Pesan sekarang</a><a class=\"btn kedua\" href=\"#\">Lihat menu lengkap</a></div>\n  </div>\n  <div class=\"gambar\" role=\"img\" aria-label=\"Secangkir kopi\"></div>\n</section>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.hero { display: grid; gap: 24px; padding: 32px 16px; background: #FFF8EE; }\n@media (min-width: 768px) { .hero { grid-template-columns: 1fr 1fr; align-items: center; padding: 64px 48px; } }\nh1 { font-size: clamp(1.75rem, 1rem + 3vw, 3rem); line-height: 1.15; margin: 0 0 12px; color: #3E2723; }\n.teks p { margin: 0 0 24px; color: #5D4037; max-width: 45ch; }\n.aksi { display: flex; gap: 12px; }\n.btn { padding: 12px 20px; border-radius: 12px; text-decoration: none; font-weight: 600; white-space: nowrap; }\n.utama { background: #6D4C41; color: #fff; }\n.kedua { border: 1px solid #6D4C41; color: #6D4C41; }\n.gambar { aspect-ratio: 4 / 3; border-radius: 24px; background: radial-gradient(circle at 40% 40%, #D7B899, #6D4C41); }","task":{"q":"Beri <code>.aksi</code> <code>flex-wrap: wrap</code> agar tombol turun baris di layar sempit.","test":"getComputedStyle(document.querySelector('.aksi')).flexWrap==='wrap'","hint":".aksi { flex-wrap: wrap }"},"pts":["Hero: h1, penjelas singkat, 1–2 tombol, gambar.","Dua kolom di desktop, satu kolom di mobile.","flex-wrap agar tombol tidak memaksa halaman melebar."],"q":[["Kenapa grup tombol hero diberi flex-wrap?",["Agar tombol turun baris di layar sempit","Agar tombol berwarna","Agar animasi jalan"],0,"Tidak ada scroll horizontal."]],"so":[{"q":"Tulis CSS hero dua kolom mulai 900px, dengan gambar di atas teks pada mobile.","h":"Mobile: order gambar -1. Desktop: grid 2 kolom dan order normal.","a":".hero { display: grid; gap: 24px; }\n.hero .gambar { order: -1; }\n@media (min-width: 900px) {\n  .hero { grid-template-columns: 1.1fr 1fr; align-items: center; }\n  .hero .gambar { order: 0; }\n}","lang":"css"}]},{"b":["Komponen di Figma (tombol, kartu, badge) ditulis <b>sekali</b> sebagai kelas CSS, lalu dipakai ulang. Ambil semua <b>variant</b>-nya dari component set: ukuran, warna, state. Jangan lupa state yang tidak terlihat di frame utama: <b>hover</b>, <b>focus-visible</b>, <b>active</b>, <b>disabled</b>.","Efek hover kartu di desain sering berupa bayangan yang lebih tebal dan kartu sedikit naik. Tulis dengan <code>transition</code> agar halus (150 sampai 250 ms), dan hormati pengguna yang mematikan animasi dengan <code>@media (prefers-reduced-motion: reduce)</code>.","Nilai bayangan Figma <code>X 0, Y 8, Blur 24, Spread 0, #000 12%</code> menjadi <code>box-shadow: 0 8px 24px rgb(0 0 0 / .12)</code>.","Kartu menu di pratinjau belum punya efek hover."],"html":"<div class=\"grid\">\n  <article class=\"kartu\"><div class=\"foto\"></div><h3>Kopi Susu Aren</h3><p>Rp22.000</p></article>\n  <article class=\"kartu\"><div class=\"foto\"></div><h3>Americano</h3><p>Rp18.000</p></article>\n</div>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 16px; padding: 16px; }\n.kartu { background: #fff; border-radius: 16px; padding: 12px; box-shadow: 0 1px 3px rgb(0 0 0 / .12); transition: box-shadow .2s, transform .2s; }\n.kartu h3 { margin: 12px 0 4px; font-size: 16px; }\n.kartu p { margin: 0; color: #6D4C41; font-weight: 600; }\n.foto { aspect-ratio: 1; border-radius: 12px; background: #D7B899; }\n@media (prefers-reduced-motion: reduce) { .kartu { transition: none; } }","task":{"q":"Tambahkan aturan <code>.kartu:hover</code> dengan <code>box-shadow: 0 8px 24px rgb(0 0 0 / .12)</code> dan <code>transform: translateY(-2px)</code>.","test":"[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText&&r.selectorText.includes('.kartu:hover')&&r.style.boxShadow&&r.style.transform.includes('translateY'))","hint":".kartu:hover { box-shadow: 0 8px 24px rgb(0 0 0 / .12); transform: translateY(-2px) }"},"pts":["Satu komponen Figma = satu kelas CSS dengan semua variant dan state.","Transisi 150–250 ms dan prefers-reduced-motion.","Bayangan Figma X Y Blur Spread → box-shadow."],"q":[["Drop shadow Figma Y 4, Blur 12, hitam 10% menjadi?",["box-shadow: 0 4px 12px rgb(0 0 0 / .1)","shadow: 4 12","text-shadow: 4px"],0,"Urutan: x y blur warna."]],"so":[{"q":"Tulis tombol primary dengan state hover, focus-visible, active, dan disabled.","h":"Lima aturan untuk satu komponen.","a":".btn-primary { background: #4F46E5; color: #fff; padding: 12px 20px; border: 0; border-radius: 12px; font-weight: 600; transition: background .15s; }\n.btn-primary:hover { background: #4338CA; }\n.btn-primary:focus-visible { outline: 3px solid #A5B4FC; outline-offset: 2px; }\n.btn-primary:active { transform: translateY(1px); }\n.btn-primary:disabled { background: #C7D2FE; cursor: not-allowed; }","lang":"css"}]},{"b":["Ekspor dari Figma: <b>ikon</b> sebagai SVG (pilih ikon, Export, SVG), lalu sisipkan inline atau sebagai <code>&lt;img&gt;</code>. <b>Foto</b> sebagai WebP atau AVIF, dengan lebar 1× dan 2× ukuran tampilannya. Foto 4000 px untuk kartu 300 px membuat halaman lambat terutama di koneksi seluler.","Setiap <code>&lt;img&gt;</code> wajib: <code>alt</code> (deskripsi singkat, atau <code>alt=\"\"</code> jika dekoratif), <code>width</code> dan <code>height</code> (agar browser menyiapkan ruang dan halaman tidak \"melompat\" saat gambar dimuat, yang diukur sebagai CLS), serta <code>loading=\"lazy\"</code> untuk gambar di bawah layar pertama.","Gambar hero di layar pertama justru <b>jangan</b> diberi lazy; beri <code>fetchpriority=\"high\"</code> agar dimuat paling awal.","Gambar di pratinjau belum punya atribut penting."],"html":"<section class=\"galeri\">\n  <img src=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 4 3'%3E%3Crect width='4' height='3' fill='%23D7B899'/%3E%3C/svg%3E\">\n</section>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.galeri { padding: 16px; }\n.galeri img { max-width: 100%; height: auto; border-radius: 12px; display: block; }","task":{"q":"Beri gambar <code>alt=\"Biji kopi Gayo\"</code>, <code>width=\"400\"</code>, <code>height=\"300\"</code>, dan <code>loading=\"lazy\"</code>.","test":"(i=>i.alt.length>0&&i.getAttribute('width')&&i.getAttribute('height')&&i.loading==='lazy')(document.querySelector('.galeri img'))","hint":"<img src=\"...\" alt=\"Biji kopi Gayo\" width=\"400\" height=\"300\" loading=\"lazy\">"},"pts":["Ikon SVG, foto WebP/AVIF 1× dan 2×.","alt, width, height, loading=\"lazy\".","Gambar hero: tanpa lazy, fetchpriority=\"high\"."],"q":[["Kenapa img diberi width dan height?",["Agar halaman tidak melompat saat gambar dimuat","Agar gambar lebih tajam","Wajib untuk SEO"],0,"Browser menyiapkan ruang lebih dulu (mengurangi CLS)."],["Gambar hero di bagian paling atas sebaiknya?",["loading=\"lazy\"","Tanpa lazy, fetchpriority=\"high\""],1,"Harus dimuat paling awal."]],"so":[{"q":"Tulis tag gambar hero yang dimuat paling awal, dan gambar galeri yang dimuat lambat.","h":"Hero: fetchpriority high tanpa lazy. Galeri: loading lazy.","a":"<img src=\"hero.webp\" alt=\"Barista menuang susu\" width=\"1200\" height=\"800\" fetchpriority=\"high\">\n<img src=\"galeri-1.webp\" alt=\"Interior kedai\" width=\"600\" height=\"400\" loading=\"lazy\">","lang":"html"}]},{"b":["Section fitur biasanya: judul section, subjudul, lalu 3 sampai 6 kartu berisi ikon, judul, dan teks singkat. Di desain desktop 3 kolom, tablet 2 kolom, ponsel 1 kolom. Dengan <code>repeat(auto-fit, minmax(240px, 1fr))</code>, kamu tidak perlu menulis media query sama sekali.","Ukur <b>gap</b> antar kartu dan <b>jarak</b> judul section ke grid dari desain. Biasanya judul section rata tengah dengan lebar teks terbatas, sedangkan isi kartu rata kiri.","Ikon di kartu fitur sering diletakkan di dalam lingkaran atau kotak berwarna lembut. Buat dengan <code>display: grid; place-items: center</code> dan ukuran tetap (48 × 48).","Grid fitur di pratinjau belum dibuat."],"html":"<section class=\"fitur\">\n  <h2>Kenapa belajar di sini?</h2>\n  <div class=\"grid\">\n    <article><span class=\"ikon\">⚡</span><h3>Langsung praktik</h3><p>Editor jalan di browser, tanpa instalasi.</p></article>\n    <article><span class=\"ikon\">🇮🇩</span><h3>Bahasa Indonesia</h3><p>Penjelasan runtut dengan contoh lokal.</p></article>\n    <article><span class=\"ikon\">📱</span><h3>Bisa offline</h3><p>Pasang sebagai aplikasi di ponsel.</p></article>\n  </div>\n</section>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.fitur { padding: 48px 16px; max-width: 1080px; margin: 0 auto; }\n.fitur h2 { text-align: center; margin: 0 0 32px; }\n.grid article { padding: 24px; border-radius: 16px; background: #F5F7FA; }\n.grid h3 { margin: 16px 0 8px; font-size: 18px; }\n.grid p { margin: 0; color: #52606D; }\n.ikon { width: 48px; height: 48px; display: grid; place-items: center; border-radius: 12px; background: #E0F2F1; font-size: 22px; }","task":{"q":"Jadikan <code>.grid</code> grid fluid: <code>display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px</code>.","test":"getComputedStyle(document.querySelector('.grid')).display==='grid'&&parseFloat(getComputedStyle(document.querySelector('.grid')).rowGap)===24&&[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText==='.grid'&&/auto-(fit|fill)/.test(r.style.gridTemplateColumns))","hint":".grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px }"},"pts":["auto-fit + minmax: 1–3 kolom tanpa media query.","Judul section rata tengah, isi kartu rata kiri.","Ikon dalam kotak 48 × 48 dengan place-items: center."],"q":[["Keuntungan auto-fit minmax untuk section fitur?",["Jumlah kolom menyesuaikan lebar tanpa media query","Kartu berwarna otomatis","Mengurutkan kartu"],0,"Grid menghitung sendiri."]],"so":[{"q":"Buat grid fitur yang tepat 3 kolom di desktop (≥ 1024px), 2 kolom di tablet, 1 kolom di ponsel, memakai media query.","h":"Mobile-first dengan min-width.","a":".grid { display: grid; gap: 24px; }\n@media (min-width: 640px) { .grid { grid-template-columns: repeat(2, 1fr); } }\n@media (min-width: 1024px) { .grid { grid-template-columns: repeat(3, 1fr); } }","lang":"css"}]},{"b":["Desain mobile sering menampilkan testimoni sebagai <b>carousel</b> yang digeser horizontal. Kamu tidak perlu library JavaScript: CSS <b>scroll-snap</b> sudah cukup. Wadahnya <code>display: flex; overflow-x: auto; scroll-snap-type: x mandatory</code>, setiap kartu <code>scroll-snap-align: start</code> dan lebar tetap (misalnya 85% layar).","Sisakan sebagian kartu berikutnya terlihat (peek) agar pengguna tahu bisa digeser. Pastikan carousel juga bisa digeser dengan keyboard (beri <code>tabindex=\"0\"</code> dan label pada wadah), dan jangan memutar otomatis tanpa tombol jeda.","Di desktop, carousel yang sama bisa berubah menjadi grid tiga kolom dengan media query.","Wadah testimoni di pratinjau sudah menggulir, tetapi belum \"mengunci\" ke kartu."],"html":"<section class=\"testi\" aria-label=\"Testimoni siswa\" tabindex=\"0\">\n  <blockquote class=\"k\">\"Akhirnya paham flexbox setelah 3 hari.\"<cite>Rina, Medan</cite></blockquote>\n  <blockquote class=\"k\">\"Proyek slicing pertamaku diterima klien.\"<cite>Andi, Makassar</cite></blockquote>\n  <blockquote class=\"k\">\"Materinya runtut dan ada soal latihannya.\"<cite>Sari, Bandung</cite></blockquote>\n</section>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.testi { display: flex; gap: 12px; overflow-x: auto; padding: 16px; }\n.k { flex: 0 0 85%; margin: 0; padding: 24px; border-radius: 16px; background: #EEF2FF; font-size: 17px; }\n.k cite { display: block; margin-top: 12px; font-size: 14px; font-style: normal; color: #4338CA; }","task":{"q":"Tambahkan <code>scroll-snap-type: x mandatory</code> pada <code>.testi</code> dan <code>scroll-snap-align: start</code> pada <code>.k</code>.","test":"getComputedStyle(document.querySelector('.testi')).scrollSnapType.includes('x')&&getComputedStyle(document.querySelector('.k')).scrollSnapAlign.includes('start')","hint":".testi { scroll-snap-type: x mandatory } .k { scroll-snap-align: start }"},"pts":["Carousel tanpa JS: overflow-x + scroll-snap.","Sisakan peek kartu berikutnya.","Bisa digeser keyboard, jangan autoplay tanpa jeda."],"q":[["Kenapa kartu carousel dibuat 85% lebar, bukan 100%?",["Agar kartu berikutnya terlihat sedikit sebagai petunjuk bisa digeser","Agar hemat memori","Aturan CSS"],0,"Peek memberi isyarat."]],"so":[{"q":"Ubah carousel testimoni menjadi grid 3 kolom tanpa scroll di layar ≥ 1024px.","h":"Di media query, ganti display dan matikan overflow.","a":"@media (min-width: 1024px) {\n  .testi { display: grid; grid-template-columns: repeat(3, 1fr); overflow: visible; }\n  .k { flex: none; }\n}","lang":"css"}]},{"b":["Section harga berisi 2 sampai 4 kartu paket: nama, harga, periode, daftar fitur, dan tombol. Satu paket biasanya <b>ditonjolkan</b> (paling populer) dengan border tebal warna merek, lencana, dan tombol primary, sementara paket lain memakai tombol secondary.","Tulis harga dengan format lokal yang benar: <b>Rp49.000</b> per bulan (titik sebagai pemisah ribuan, tanpa spasi setelah Rp). Fitur ditulis sebagai daftar <code>&lt;ul&gt;</code> dengan tanda centang; fitur yang tidak termasuk jangan hanya diberi warna abu-abu, beri juga teks atau ikon silang.","Agar tombol semua kartu sejajar di bawah walau daftar fiturnya beda panjang, jadikan kartu <code>display: flex; flex-direction: column</code> dan beri tombol <code>margin-top: auto</code>.","Kartu Pro di pratinjau harus menjadi paket unggulan."],"html":"<section class=\"harga\">\n  <article class=\"paket\"><h3>Gratis</h3><p class=\"h\">Rp0</p><ul><li>✓ 50 pelajaran</li></ul><a href=\"#\" class=\"b\">Mulai</a></article>\n  <article class=\"paket pro\"><h3>Pro</h3><p class=\"h\">Rp49.000<small>/bulan</small></p><ul><li>✓ Semua pelajaran</li><li>✓ Sertifikat</li><li>✓ Proyek dinilai mentor</li></ul><a href=\"#\" class=\"b\">Pilih Pro</a></article>\n</section>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.harga { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; padding: 16px; }\n.paket { display: flex; flex-direction: column; padding: 24px; border: 1px solid #D5D9E0; border-radius: 16px; }\n.paket h3 { margin: 0; }\n.h { font-size: 28px; font-weight: 700; margin: 8px 0 16px; }\n.h small { font-size: 14px; font-weight: 400; color: #52606D; }\n.paket ul { list-style: none; padding: 0; margin: 0 0 24px; display: grid; gap: 8px; }\n.b { margin-top: auto; text-align: center; padding: 12px; border-radius: 12px; border: 1px solid #1D5FA8; color: #1D5FA8; text-decoration: none; font-weight: 600; }","task":{"q":"Tonjolkan paket Pro: <code>.pro</code> diberi <code>border: 2px solid #1D5FA8</code>, dan tombolnya (<code>.pro .b</code>) berlatar <code>#1D5FA8</code> dengan teks putih.","test":"parseFloat(getComputedStyle(document.querySelector('.pro')).borderTopWidth)>=2&&getComputedStyle(document.querySelector('.pro .b')).backgroundColor==='rgb(29, 95, 168)'","hint":".pro { border: 2px solid #1D5FA8 } .pro .b { background: #1D5FA8; color: #fff }"},"pts":["Satu paket unggulan: border, lencana, tombol primary.","Format harga Rp49.000.","Tombol sejajar bawah: flex column + margin-top: auto."],"q":[["Cara membuat tombol semua kartu sejajar di bawah?",["Kartu flex column, tombol margin-top: auto","Tinggi kartu tetap 500px","position: absolute"],0,"Ruang kosong dipakai margin auto."]],"so":[{"q":"Tambahkan lencana \"Paling populer\" di kartu Pro dan fitur yang tidak termasuk di kartu Gratis dengan ikon dan teks.","h":"Jangan hanya abu-abu; tulis \"Tidak termasuk\".","a":"<article class=\"paket pro\">\n  <span class=\"lencana\">Paling populer</span>\n  ...\n</article>\n<article class=\"paket\">\n  <ul>\n    <li>✓ 50 pelajaran</li>\n    <li class=\"tidak\">✕ Sertifikat <span class=\"sr-only\">(tidak termasuk)</span></li>\n  </ul>\n</article>","lang":"html"}]},{"b":["Footer berisi kelompok link (Produk, Perusahaan, Bantuan), media sosial, form newsletter, dan hak cipta. Di desktop kelompok link berdampingan; di mobile bertumpuk atau dilipat.","Form newsletter di desain sering hanya menampilkan input dengan placeholder \"Email kamu\" dan tombol. Input tetap butuh <b>label</b>; jika desain tidak menampilkannya, sembunyikan secara visual dengan kelas <code>.sr-only</code> tetapi tetap terbaca pembaca layar. Pakai <code>type=\"email\"</code> dan <code>autocomplete=\"email\"</code> agar keyboard ponsel menampilkan tombol @.","Ikon media sosial yang hanya berupa ikon wajib punya <code>aria-label</code> (\"Instagram Ruang Kode\").","Form newsletter di pratinjau belum punya label dan tipe input yang tepat."],"html":"<footer class=\"kaki\">\n  <form class=\"news\">\n    <input id=\"surel\" placeholder=\"Email kamu\">\n    <button>Langganan</button>\n  </form>\n  <p>© 2026 RuangKode</p>\n</footer>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.kaki { padding: 32px 16px; background: #0F172A; color: #CBD5E1; }\n.news { display: flex; gap: 8px; flex-wrap: wrap; max-width: 420px; }\n.news input { flex: 1; min-width: 200px; padding: 12px; border-radius: 10px; border: 1px solid #475569; background: #1E293B; color: #fff; font-size: 16px; }\n.news button { padding: 12px 20px; border: 0; border-radius: 10px; background: #F59E0B; color: #1F2933; font-weight: 600; }\n.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }","task":{"q":"Tambahkan <code>&lt;label class=\"sr-only\" for=\"surel\"&gt;Email&lt;/label&gt;</code>, lalu beri input <code>type=\"email\"</code> dan <code>autocomplete=\"email\"</code>.","test":"!!document.querySelector('label[for=\"surel\"]')&&document.getElementById('surel').type==='email'&&document.getElementById('surel').autocomplete==='email'","hint":"<label class=\"sr-only\" for=\"surel\">Email</label><input id=\"surel\" type=\"email\" autocomplete=\"email\" placeholder=\"Email kamu\">"},"pts":["Label tetap ada; sembunyikan secara visual dengan .sr-only.","type=\"email\" dan autocomplete=\"email\".","Ikon sosial butuh aria-label."],"q":[["Desain tidak menampilkan label input. Solusi yang benar?",["Hapus label","Label dengan kelas sr-only","Pakai placeholder saja"],1,"Tetap terbaca pembaca layar."]],"so":[{"q":"Tulis tautan ikon Instagram dan YouTube yang aksesibel.","h":"aria-label pada tautan, aria-hidden pada ikon.","a":"<a href=\"https://instagram.com/ruangkode\" aria-label=\"Instagram Ruang Kode\"><svg aria-hidden=\"true\" width=\"24\" height=\"24\">...</svg></a>\n<a href=\"https://youtube.com/@ruangkode\" aria-label=\"YouTube Ruang Kode\"><svg aria-hidden=\"true\" width=\"24\" height=\"24\">...</svg></a>","lang":"html"}]},{"b":["Desainer biasanya memberi dua atau tiga frame: mobile (360 atau 390), tablet (768), dan desktop (1440). <b>Mobile-first</b> berarti CSS dasar ditulis untuk mobile, lalu ditambah dengan <code>@media (min-width: ...)</code> untuk layar yang lebih lebar. Kodenya lebih ringkas daripada sebaliknya.","Breakpoint diambil dari titik desain <b>berubah</b>, bukan dari nama perangkat. Jika frame tablet menunjukkan kartu menjadi 2 kolom, tulis <code>@media (min-width: 768px)</code>. Di antara dua frame, bayangkan sendiri perilakunya: apa yang melar, apa yang dibatasi lebar maksimumnya.","Uji di DevTools (Ctrl + Shift + M) dengan menyeret lebar layar pelan-pelan dari 320 sampai 1600 px. Bagian yang rusak di lebar \"tanggung\" seperti 900 px sering terlewat jika hanya mengecek tiga ukuran frame.","Daftar kelas di pratinjau satu kolom. Buat 2 kolom mulai lebar 600px."],"html":"<ul class=\"daftar\">\n  <li>HTML</li><li>CSS</li><li>JavaScript</li><li>Figma</li>\n</ul>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.daftar { list-style: none; margin: 0; padding: 16px; display: grid; gap: 12px; }\n.daftar li { padding: 16px; border-radius: 12px; background: #F0FDFA; font-weight: 600; }\n/* tulis media query di bawah */","task":{"q":"Tambahkan <code>@media (min-width: 600px) { .daftar { grid-template-columns: 1fr 1fr; } }</code>.","test":"[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.media&&/min-width/.test(r.media.mediaText)&&[...r.cssRules].some(x=>x.selectorText==='.daftar'&&x.style.gridTemplateColumns))","hint":"@media (min-width: 600px) { .daftar { grid-template-columns: 1fr 1fr } }"},"pts":["CSS dasar untuk mobile, tambah dengan min-width.","Breakpoint dari titik desain berubah.","Seret lebar layar pelan-pelan, jangan hanya 3 ukuran."],"q":[["Mobile-first memakai media query?",["min-width","max-width"],0,"Aturan ditambahkan saat layar melebar."]],"so":[{"q":"Desain punya frame 390 (1 kolom kartu), 834 (2 kolom), 1440 (4 kolom, lebar konten maks 1200). Tulis rencana breakpoint dan CSS-nya.","h":"Breakpoint dari titik perubahan; container maks 1200.","a":".wrap { max-width: 1200px; margin: 0 auto; padding: 0 16px; }\n.grid { display: grid; gap: 16px; }\n@media (min-width: 768px)  { .grid { grid-template-columns: repeat(2, 1fr); } }\n@media (min-width: 1200px) { .grid { grid-template-columns: repeat(4, 1fr); } }","lang":"text"}]},{"b":["Satu gambar besar untuk semua layar membuang kuota pengguna ponsel. Atribut <code>srcset</code> memberi browser beberapa pilihan file, dan <code>sizes</code> memberi tahu lebar tampil gambar. Browser lalu memilih file terkecil yang tetap tajam untuk layar itu.","Contoh: <code>srcset=\"kopi-480.webp 480w, kopi-960.webp 960w, kopi-1440.webp 1440w\"</code> dan <code>sizes=\"(min-width: 768px) 50vw, 100vw\"</code>. Artinya: di layar lebar gambar tampil selebar setengah layar, di ponsel selebar penuh.","Jika desain meminta <b>potongan berbeda</b> (art direction), misalnya foto lebar di desktop tetapi potongan persegi di mobile, pakai <code>&lt;picture&gt;</code> dengan beberapa <code>&lt;source media=\"...\"&gt;</code>.","Gambar di pratinjau hanya punya satu file."],"html":"<img class=\"foto\" src=\"kopi-960.webp\" alt=\"Barista menyeduh kopi\" width=\"960\" height=\"640\">","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.foto { display: block; max-width: 100%; height: auto; background: #D7B899; }","task":{"q":"Tambahkan <code>srcset</code> dengan tiga ukuran (480w, 960w, 1440w) dan <code>sizes=\"(min-width: 768px) 50vw, 100vw\"</code>.","test":"(i=>(i.getAttribute('srcset')||'').split(',').length>=3&&/\\d+w/.test(i.getAttribute('srcset'))&&!!i.getAttribute('sizes'))(document.querySelector('.foto'))","hint":"srcset=\"kopi-480.webp 480w, kopi-960.webp 960w, kopi-1440.webp 1440w\" sizes=\"(min-width: 768px) 50vw, 100vw\""},"pts":["srcset: daftar file dengan lebar aslinya (w).","sizes: lebar tampil gambar di setiap kondisi.","picture + source untuk potongan berbeda."],"q":[["Apa arti 960w di srcset?",["Lebar asli file 960 piksel","Tampilkan 960 piksel","Lebar layar 960"],0,"Browser memakai info ini untuk memilih."]],"so":[{"q":"Tulis elemen picture: desktop memakai foto lebar 16:9, ponsel memakai potongan persegi.","h":"source dengan media min-width untuk desktop, img sebagai cadangan.","a":"<picture>\n  <source media=\"(min-width: 768px)\" srcset=\"hero-lebar-1280.webp 1280w, hero-lebar-1920.webp 1920w\" sizes=\"100vw\">\n  <img src=\"hero-persegi-720.webp\" srcset=\"hero-persegi-480.webp 480w, hero-persegi-720.webp 720w\" sizes=\"100vw\" alt=\"Kedai KopiNusa\" width=\"720\" height=\"720\">\n</picture>","lang":"html"}]},{"b":["<b>Pixel-perfect</b> berarti hasil slicing sesuai desain sampai detail: jarak, ukuran huruf, warna, radius, bayangan. Ini bukan soal obsesi 1 piksel, melainkan menghormati keputusan desainer dan menjaga konsistensi produk.","Cara membandingkan: (1) ekspor frame desain sebagai PNG pada lebar yang sama; (2) buka hasilmu di DevTools device mode dengan lebar yang sama; (3) pakai ekstensi overlay seperti <b>PerfectPixel</b> untuk menumpuk gambar desain semi-transparan di atas halaman; (4) atau letakkan tangkapan layar berdampingan dan periksa per section.","Prioritaskan perbedaan berdasarkan dampak: <b>tinggi</b> (warna salah, font salah, elemen hilang, layout rusak di ukuran tertentu), <b>sedang</b> (jarak antar section, ukuran ikon), <b>rendah</b> (selisih 1 sampai 2 px yang disebabkan perbedaan render font antar sistem operasi). Diskusikan dengan desainer perbedaan yang memang tidak bisa dihindari."],"tb":[{"c":"Daftar periksa visual per section","h":["Periksa","Cara"],"r":[["Font dan ketebalan","DevTools → Computed → font-family, font-weight"],["Ukuran dan line-height","Bandingkan dengan panel Figma"],["Warna","Eyedropper DevTools vs nilai variabel Figma"],["Jarak antar elemen","Hover di DevTools menampilkan margin dan padding"],["Radius dan bayangan","Bandingkan dengan overlay"],["Lebar maksimum konten","Cek di 1440 dan 1920 px"],["Teks panjang","Ganti teks dengan kalimat 2× lebih panjang"],["State","Hover, focus, disabled sesuai desain"]]}],"pts":["Pixel-perfect: jarak, huruf, warna, radius, bayangan sesuai desain.","Bandingkan di lebar yang sama dengan overlay.","Prioritaskan berdasarkan dampak."],"q":[["Perbedaan mana yang paling penting diperbaiki dulu?",["Selisih 1 px karena render font","Warna tombol utama salah","Bayangan sedikit lebih tipis"],1,"Dampaknya paling terlihat dan merusak konsistensi merek."]],"so":[{"q":"Kamu menemukan 5 perbedaan: (a) tombol radius 8 seharusnya 12, (b) font fallback tampil karena salah nama, (c) jarak section 64 seharusnya 80, (d) teks 1 px lebih tinggi di Windows, (e) menu mobile tidak muncul. Urutkan prioritasnya.","h":"Dampak terbesar dulu.","a":"1. (e) menu mobile tidak muncul (fungsi rusak)\n2. (b) font salah (merusak tampilan seluruh halaman)\n3. (c) jarak section\n4. (a) radius tombol\n5. (d) selisih render font antar OS: catat, umumnya diterima","lang":"text"}]},{"b":["Desain jarang menunjukkan hal yang tidak terlihat, padahal itu tanggung jawab slicer: <b>urutan fokus</b> keyboard yang logis, <b>indikator fokus</b> yang jelas, <b>alt</b> gambar, <b>label</b> form, <b>bahasa</b> halaman (<code>&lt;html lang=\"id\"&gt;</code>), dan <b>skip link</b>.","<b>Skip link</b> adalah tautan pertama di halaman, tersembunyi sampai difokuskan dengan Tab, yang langsung melompat ke konten utama. Pengguna keyboard tidak perlu melewati 15 link navbar di setiap halaman.","Uji cepat setelah slicing: tekan Tab dari atas sampai bawah tanpa mouse; jalankan Lighthouse (tab Lighthouse di DevTools, kategori Accessibility); zoom browser 200% dan pastikan tidak ada teks terpotong atau scroll horizontal.","Halaman di pratinjau belum punya skip link."],"html":"<header class=\"nav\"><a href=\"#\">Beranda</a><a href=\"#\">Kelas</a><a href=\"#\">Harga</a><a href=\"#\">Blog</a><a href=\"#\">Masuk</a></header>\n<main><h1>Kelas Slicing Website</h1><p>Konten utama halaman.</p></main>","css":"body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.nav { display: flex; gap: 12px; flex-wrap: wrap; padding: 12px 16px; border-bottom: 1px solid #E4E7EB; }\nmain { padding: 24px 16px; }\n.skip { position: absolute; left: 8px; top: -48px; background: #1F2933; color: #fff; padding: 8px 12px; border-radius: 8px; }\n.skip:focus { top: 8px; }","task":{"q":"Tambahkan <code>&lt;a class=\"skip\" href=\"#isi\"&gt;Lewati ke konten&lt;/a&gt;</code> sebagai elemen pertama, dan beri <code>main</code> <code>id=\"isi\"</code>.","test":"(a=>!!a&&a.classList.contains('skip')&&a.getAttribute('href')==='#isi')(document.body.querySelector('a'))&&!!document.querySelector('main#isi')","hint":"<a class=\"skip\" href=\"#isi\">Lewati ke konten</a> di paling atas, lalu <main id=\"isi\">"},"pts":["Slicer bertanggung jawab atas fokus, alt, label, lang, skip link.","Skip link melompati navigasi.","Uji: Tab, Lighthouse, zoom 200%."],"q":[["Siapa yang paling diuntungkan skip link?",["Pengguna keyboard dan pembaca layar","Mesin pencari","Desainer"],0,"Tidak perlu melewati navigasi berulang."]],"so":[{"q":"Tulis 5 langkah uji aksesibilitas cepat yang bisa kamu lakukan dalam 10 menit setelah slicing.","h":"Keyboard, Lighthouse, zoom, alt, kontras.","a":"1. Tekan Tab dari atas ke bawah: urutan logis dan fokus terlihat.\n2. Lighthouse → Accessibility, perbaiki semua temuan merah.\n3. Zoom 200%: tidak ada teks terpotong atau scroll horizontal.\n4. Matikan gambar atau baca alt di DevTools: alt bermakna.\n5. Cek kontras teks abu-abu dengan DevTools color picker.","lang":"text"}]},{"b":["Saatnya menggabungkan semua: navbar sticky, hero, fitur, harga, dan footer dalam satu halaman. Kerangka di pratinjau sudah memakai token, HTML semantik, dan grid fluid. Lengkapi bagian yang belum sesuai desain.","Spesifikasi desain: navbar menempel di atas saat menggulir, hero dua kolom mulai 768 px, kartu menu memakai grid auto-fill minimal 180 px, dan semua warna dari token.","Setelah tantangan selesai, salin kode ke VS Code, buka dengan Live Server, lalu uji di ponselmu lewat jaringan Wi-Fi yang sama. Langkah berikutnya: deploy, dibahas di pelajaran selanjutnya."],"html":"<header class=\"nav\"><a class=\"logo\" href=\"#\">Kopi<b>Nusa</b></a><a class=\"btn\" href=\"#menu\">Pesan</a></header>\n<main>\n  <section class=\"hero\"><div><h1>Kopi lokal, diseduh hari ini</h1><p>Gayo, Toraja, Kintamani. Diantar 30 menit.</p><a class=\"btn\" href=\"#menu\">Lihat menu</a></div><div class=\"foto\" role=\"img\" aria-label=\"Kopi\"></div></section>\n  <section id=\"menu\" class=\"menu\"><h2>Menu favorit</h2>\n    <div class=\"grid\"><article class=\"kartu\"><h3>Kopi Susu Aren</h3><p>Rp22.000</p></article><article class=\"kartu\"><h3>Americano</h3><p>Rp18.000</p></article><article class=\"kartu\"><h3>Kopi Tubruk</h3><p>Rp15.000</p></article></div>\n  </section>\n</main>\n<footer class=\"kaki\">© 2026 KopiNusa</footer>","css":":root { --brand: #6D4C41; --brand-soft: #FFF8EE; --ink: #3E2723; --radius: 16px; --space: 16px; }\nbody { font-family: system-ui, sans-serif; margin: 0; color: var(--ink); }\n.nav { display: flex; justify-content: space-between; align-items: center; padding: 12px var(--space); background: #fff; border-bottom: 1px solid #E7E0D8; }\n.logo { color: var(--ink); text-decoration: none; font-size: 20px; }\n.btn { display: inline-block; background: var(--brand); color: #fff; padding: 10px 18px; border-radius: 999px; text-decoration: none; font-weight: 600; }\n.hero { display: grid; gap: 24px; padding: 32px var(--space); background: var(--brand-soft); }\n@media (min-width: 768px) { .hero { grid-template-columns: 1fr 1fr; align-items: center; } }\n.hero h1 { font-size: clamp(1.75rem, 1rem + 3vw, 3rem); margin: 0 0 12px; }\n.foto { aspect-ratio: 4 / 3; border-radius: 24px; background: radial-gradient(circle at 40% 40%, #D7B899, var(--brand)); }\n.menu { padding: 32px var(--space); }\n.kartu { padding: var(--space); border-radius: var(--radius); background: #F5F0EB; }\n.kartu h3 { margin: 0 0 4px; font-size: 16px; }\n.kartu p { margin: 0; font-weight: 600; color: var(--brand); }\n.kaki { padding: 24px var(--space); background: var(--ink); color: #EFE6DD; }","task":{"q":"Selesaikan dua hal: navbar <code>.nav</code> menempel (<code>position: sticky; top: 0; z-index: 10</code>), dan <code>.grid</code> menjadi grid fluid <code>repeat(auto-fill, minmax(180px, 1fr))</code> dengan gap 16px.","test":"getComputedStyle(document.querySelector('.nav')).position==='sticky'&&getComputedStyle(document.querySelector('.grid')).display==='grid'&&[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText==='.grid'&&/auto-(fill|fit)/.test(r.style.gridTemplateColumns))","hint":".nav { position: sticky; top: 0; z-index: 10 } .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 16px }"},"pts":["Gabungkan token, HTML semantik, flex, dan grid.","Uji di ponsel lewat Live Server.","Selesaikan spesifikasi sebelum menambah hiasan."],"q":[["Kenapa navbar sticky butuh z-index?",["Agar konten yang digulir tidak tampil di atasnya","Agar lebih cepat","Agar berwarna"],0,"Navbar tetap di lapisan atas."]],"so":[{"q":"Tambahkan section FAQ ke proyek memakai details/summary, dengan gaya yang memakai token proyek.","h":"details untuk setiap pertanyaan, summary sebagai pertanyaan.","a":".faq details { border-bottom: 1px solid #E7E0D8; padding: var(--space) 0; }\n.faq summary { cursor: pointer; font-weight: 600; color: var(--ink); }\n.faq summary::marker { color: var(--brand); }\n.faq p { margin: 8px 0 0; }","lang":"css"}]},{"b":["Klien ingin melihat hasilnya di internet, bukan file zip. Tiga cara gratis yang paling umum: <b>GitHub Pages</b> (push ke repositori, aktifkan Pages di Settings), <b>Netlify</b> (seret folder ke app.netlify.com/drop), dan <b>Vercel</b> (hubungkan repositori GitHub, setiap push otomatis di-deploy dan setiap branch dapat URL pratinjau).","Sebelum deploy: pastikan file utama bernama <code>index.html</code>, semua path relatif (<code>./css/style.css</code>, bukan <code>C:\\Users\\...</code>), nama file huruf kecil tanpa spasi (server Linux membedakan <code>Logo.png</code> dan <code>logo.png</code>), dan gambar sudah dikompres.","Setelah deploy, kirim link ke klien dan uji sendiri di ponsel dengan data seluler (bukan Wi-Fi kantor) untuk merasakan kecepatan aslinya. Jalankan PageSpeed Insights (pagespeed.web.dev) dan catat skornya."],"lang":"bash","code":"# GitHub Pages lewat terminal\ngit init\ngit add .\ngit commit -m \"Slicing landing page KopiNusa\"\ngit branch -M main\ngit remote add origin https://github.com/namakamu/kopinusa.git\ngit push -u origin main\n# Lalu: Settings → Pages → Branch: main → Save\n# Situs tersedia di https://namakamu.github.io/kopinusa/","tb":[{"c":"Pilihan hosting gratis","h":["Layanan","Cara","Kelebihan"],"r":[["GitHub Pages","Push ke repo, aktifkan Pages","Sekalian portofolio di GitHub"],["Netlify Drop","Seret folder ke browser","Paling cepat, tanpa Git"],["Vercel","Hubungkan repo GitHub","URL pratinjau setiap branch"]]}],"pts":["GitHub Pages, Netlify, Vercel.","index.html, path relatif, nama file huruf kecil.","Uji dengan data seluler dan PageSpeed Insights."],"q":[["Gambar tampil di laptop tapi rusak setelah deploy. Penyebab paling umum?",["Beda huruf besar-kecil nama file atau path absolut","Internet lambat","Browser lama"],0,"Server Linux peka huruf besar-kecil."]],"so":[{"q":"Hasil deploy GitHub Pages tampil tanpa CSS. Path di HTML: <code>/css/style.css</code>, situs di <code>namakamu.github.io/kopinusa/</code>. Apa penyebab dan perbaikannya?","h":"Garis miring di awal merujuk ke akar domain, bukan folder proyek.","a":"Penyebab: /css/style.css dicari di namakamu.github.io/css/style.css (akar domain),\nbukan di /kopinusa/css/style.css.\nPerbaikan: pakai path relatif css/style.css atau ./css/style.css.","lang":"text"}]},{"b":["Sebelum menyerahkan hasil slicing, jalankan daftar periksa ini. Klien dan desainer akan menemukan masalah yang sama jika kamu melewatkannya, dan kesan pertama sulit diulang.","Kelompokkan pemeriksaan menjadi: <b>visual</b> (sesuai desain di 360, 768, 1440 px), <b>fungsi</b> (semua link dan tombol bekerja, form tervalidasi), <b>aksesibilitas</b> (Tab, alt, label, kontras), <b>performa</b> (gambar terkompres, skor Lighthouse), <b>kompatibilitas</b> (Chrome, Safari iOS, Firefox, Samsung Internet), dan <b>SEO dasar</b> (title, meta description, Open Graph).","Tulis laporan singkat saat serah terima: link deploy, browser yang sudah diuji, skor Lighthouse, dan daftar perbedaan dengan desain yang disengaja beserta alasannya. Laporan ini membuatmu terlihat profesional dan mencegah perdebatan di kemudian hari."],"tb":[{"c":"Daftar periksa serah terima","h":["Kelompok","Periksa"],"r":[["Visual","Sesuai desain di 360, 768, 1440 px; tidak ada scroll horizontal"],["Fungsi","Semua link, tombol, menu mobile, dan form bekerja"],["Aksesibilitas","Tab berurutan, fokus terlihat, alt, label, kontras 4,5:1"],["Performa","Gambar WebP terkompres, Lighthouse Performance ≥ 90"],["Kompatibilitas","Chrome, Safari iOS, Firefox, Samsung Internet"],["SEO","title, meta description, Open Graph, favicon, lang=\"id\""],["Konten","Tidak ada lorem ipsum, ejaan benar, format Rp dan tanggal benar"],["Serah terima","Link deploy, repositori, laporan pengujian"]]}],"pts":["Visual, fungsi, aksesibilitas, performa, kompatibilitas, SEO.","Uji di Safari iOS dan Samsung Internet juga.","Serahkan laporan pengujian."],"q":[["Browser mana yang sering terlupa diuji padahal banyak dipakai di Indonesia?",["Samsung Internet","Internet Explorer 6","Netscape"],0,"Bawaan banyak ponsel Samsung."]],"so":[{"q":"Tulis laporan serah terima singkat untuk proyek KopiNusa.","h":"Link, browser yang diuji, skor, perbedaan yang disengaja.","a":"Proyek  : Landing page KopiNusa\nLink    : https://kopinusa.vercel.app\nRepo    : github.com/namakamu/kopinusa\nDiuji di: Chrome 131, Safari iOS 18, Firefox 133, Samsung Internet 27; lebar 360, 768, 1440\nLighthouse: Performance 96, Accessibility 100, Best Practices 100, SEO 100\nPerbedaan disengaja: bayangan kartu dibuat lebih tipis di dark mode agar kontras tetap 4,5:1 (disetujui desainer 12/11).","lang":"text"}]}]);
